<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{ $quotation->number }}</title><style>body{font-family:Arial,sans-serif;margin:40px;color:#172033}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border-bottom:1px solid #dbe2ea;padding:10px;text-align:left}th:last-child,td:last-child{text-align:right}.total{text-align:right;margin-top:20px;font-size:18px}.muted{color:#64748b}</style></head><body><h1>Sales Quotation</h1><p><strong>{{ $quotation->number }}</strong><br>Version {{ $quotation->version_number }}<br>{{ $quotation->customer?->name }}<br><span class="muted">Valid until: {{ $quotation->valid_until?->format('Y-m-d') ?? '—' }}</span></p><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Discount</th><th>Tax</th><th>Total</th></tr></thead><tbody>@foreach($quotation->items as $item)<tr><td>{{ $item->description ?: $item->variant_id }}</td><td>{{ $item->quantity }}</td><td>{{ $item->unit_price }}</td><td>{{ $item->discount_amount }}</td><td>{{ $item->tax_amount }}</td><td>{{ $item->line_total }}</td></tr>@endforeach</tbody></table><p class="total">Subtotal: {{ $quotation->subtotal }}<br>Discount: {{ $quotation->discount_total }}<br>Tax: {{ $quotation->tax_total }}<br><strong>Total: {{ $quotation->total }}</strong></p><p>{{ $quotation->terms_and_conditions }}</p></body></html>
